import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as AuthUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // WorkOS user id, set once the person has signed in through AuthKit.
  authId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Links a WorkOS identity to a Notely user: matches by auth id, then by email
// (so existing users keep their record), otherwise creates a new user.
export async function upsertAuthUser(authUser: AuthUser): Promise<User> {
  const email = authUser.email.toLowerCase();
  const existing =
    users.find((u) => u.authId === authUser.id) ??
    users.find((u) => u.email.toLowerCase() === email);

  if (existing) {
    existing.authId = authUser.id;
    existing.email = authUser.email;
    return existing;
  }

  const fullName = [authUser.firstName, authUser.lastName].filter(Boolean).join(" ");
  const user: User = {
    id: String(users.length + 1),
    email: authUser.email,
    name: fullName || email.split("@")[0],
    createdAt: authUser.createdAt.slice(0, 10),
    authId: authUser.id,
  };
  users.push(user);
  return user;
}

// Returns the signed-in user. Redirects to AuthKit sign-in when there is no session.
export async function getCurrentUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return upsertAuthUser(user);
}
